using System.Globalization;
using System.Text.Json;
using Microsoft.EntityFrameworkCore;
using Sace.Api.Domain;
using Sace.Api.Infrastructure;

namespace Sace.Api.Services;

public sealed record LegalEvidenceCandidate(LegalEvidenceType EvidenceType,string Code,string SourceEntityType,Guid? SourceEntityId,string? FieldCode,string? RawValue,string? NormalizedValue,string? Outcome,double? Confidence,Guid? DocumentId,Guid? DocumentFieldId,string Explanation);
public interface ILegalEvidenceResolver { Task<IReadOnlyList<LegalEvidenceCandidate>> ResolveAsync(TradeOperation operation,NormativeRule rule,CancellationToken ct=default); }

public sealed class LegalEvidenceResolver(SaceDbContext db):ILegalEvidenceResolver {
  public async Task<IReadOnlyList<LegalEvidenceCandidate>> ResolveAsync(TradeOperation op,NormativeRule rule,CancellationToken ct=default){
    var result=new List<LegalEvidenceCandidate>();
    foreach(var requirement in rule.LegalEvidenceRequirements){
      switch(requirement.EvidenceType){
        case LegalEvidenceType.TRADE_OPERATION:
          var value=OperationValue(op,requirement.Code);if(value is not null)result.Add(Candidate(requirement,op.Id,"TradeOperation",requirement.Code,value,value,null,null,null,null,"Valor capturado en la operación."));break;
        case LegalEvidenceType.DOCUMENT:
          var docs=await db.OperationDocuments.AsNoTracking().Where(x=>x.TradeOperationId==op.Id&&x.DocumentType.Code==requirement.Code).Select(x=>new{x.Id,x.OriginalFileName}).ToListAsync(ct);
          result.AddRange(docs.Select(x=>Candidate(requirement,x.Id,"OperationDocument",null,x.OriginalFileName,x.OriginalFileName,null,null,x.Id,null,"Documento disponible en el expediente.")));break;
        case LegalEvidenceType.DOCUMENT_FIELD:
          var fields=await db.DocumentFields.AsNoTracking().Where(x=>x.OperationDocument.TradeOperationId==op.Id&&x.FieldCode==requirement.Code).Select(x=>new{x.Id,x.OperationDocumentId,x.FieldCode,x.RawValue,x.NormalizedValue,x.Confidence}).ToListAsync(ct);
          result.AddRange(fields.Select(x=>Candidate(requirement,x.Id,"DocumentField",x.FieldCode,x.RawValue,x.NormalizedValue,null,x.Confidence,x.OperationDocumentId,x.Id,"Campo documental capturado; no es una decisión jurídica.")));break;
        case LegalEvidenceType.CROSS_VALIDATION: await Cross(op,rule,requirement,result,ct);break;
        case LegalEvidenceType.VALUATION: await Valuation(op,rule,requirement,result,ct);break;
        case LegalEvidenceType.CONTRIBUTION: await Contribution(op,rule,requirement,result,ct);break;
        case LegalEvidenceType.RRNA: await Rrna(op,rule,requirement,result,ct);break;
        case LegalEvidenceType.IMMEX: await Immex(op,rule,requirement,result,ct);break;
      }
    }
    return result;
  }
  async Task Cross(TradeOperation op,NormativeRule rule,LegalEvidenceRequirement req,List<LegalEvidenceCandidate> rows,CancellationToken ct){foreach(var map in Maps(rule,req,LegalEvidenceType.CROSS_VALIDATION)){var values=await db.CrossValidationResults.AsNoTracking().Where(x=>x.TradeOperationId==op.Id).OrderByDescending(x=>x.EvaluatedAt).ToListAsync(ct);values=values.Where(x=>Matches(map.SourceOutcome,x.Outcome)).ToList();rows.AddRange(values.Select(x=>Candidate(req,x.Id,nameof(CrossValidationResult),map.SourceFieldCode,x.SourceRawValue,x.SourceNormalizedValue,x.Outcome.ToString(),x.Confidence,x.SourceDocumentId,x.SourceFieldId,x.Explanation)));}}
  async Task Valuation(TradeOperation op,NormativeRule rule,LegalEvidenceRequirement req,List<LegalEvidenceCandidate> rows,CancellationToken ct){foreach(var map in Maps(rule,req,LegalEvidenceType.VALUATION)){var values=await db.CustomsValuationCalculations.AsNoTracking().Where(x=>x.TradeOperationId==op.Id).OrderByDescending(x=>x.CalculationVersion).ToListAsync(ct);var x=values.FirstOrDefault(x=>Matches(map.SourceOutcome,x.Outcome));if(x is not null)rows.Add(Candidate(req,x.Id,nameof(CustomsValuationCalculation),null,x.DeclaredCustomsValue?.ToString(CultureInfo.InvariantCulture),x.CalculatedCustomsValue?.ToString(CultureInfo.InvariantCulture),x.Outcome.ToString(),null,null,null,x.Explanation));}}
  async Task Contribution(TradeOperation op,NormativeRule rule,LegalEvidenceRequirement req,List<LegalEvidenceCandidate> rows,CancellationToken ct){foreach(var map in Maps(rule,req,LegalEvidenceType.CONTRIBUTION)){var values=await db.ContributionCalculations.AsNoTracking().Where(x=>x.TradeOperationId==op.Id).OrderByDescending(x=>x.Version).ToListAsync(ct);var x=values.FirstOrDefault(x=>Matches(map.SourceOutcome,x.Status));if(x is not null)rows.Add(Candidate(req,x.Id,nameof(ContributionCalculation),null,null,null,x.Status.ToString(),null,null,null,x.Explanation));}}
  async Task Rrna(TradeOperation op,NormativeRule rule,LegalEvidenceRequirement req,List<LegalEvidenceCandidate> rows,CancellationToken ct){foreach(var map in Maps(rule,req,LegalEvidenceType.RRNA)){var values=await db.RegulatoryRequirementEvaluations.AsNoTracking().Where(x=>x.TradeOperationId==op.Id).OrderByDescending(x=>x.EvaluatedAt).ToListAsync(ct);values=values.Where(x=>Matches(map.SourceOutcome,x.EvidenceStatus)||Matches(map.SourceOutcome,x.AutomatedOutcome)).ToList();rows.AddRange(values.Select(x=>Candidate(req,x.Id,nameof(RegulatoryRequirementEvaluation),null,null,null,$"{x.AutomatedOutcome}/{x.EvidenceStatus}",null,null,null,x.Explanation)));}}
  async Task Immex(TradeOperation op,NormativeRule rule,LegalEvidenceRequirement req,List<LegalEvidenceCandidate> rows,CancellationToken ct){foreach(var map in Maps(rule,req,LegalEvidenceType.IMMEX)){var values=await db.ImmexInventoryEntries.AsNoTracking().Where(x=>x.TradeOperationId==op.Id).ToListAsync(ct);values=values.Where(x=>Matches(map.SourceOutcome,x.TemporalityOutcome)).ToList();rows.AddRange(values.Select(x=>Candidate(req,x.Id,nameof(ImmexInventoryEntry),"AVAILABLE_QUANTITY",x.AvailableQuantity.ToString(CultureInfo.InvariantCulture),x.AvailableQuantity.ToString(CultureInfo.InvariantCulture),x.TemporalityOutcome.ToString(),null,x.OperationDocumentId,null,"Estado técnico IMMEX capturado; requiere prueba jurídica completa.")));}}
  static IEnumerable<LegalEvidenceMapping> Maps(NormativeRule rule,LegalEvidenceRequirement req,LegalEvidenceType type)=>rule.LegalEvidenceMappings.Where(x=>x.SourceType==type&&x.TargetEvidenceCode==req.Code);
  static bool Matches<T>(string? expected,T actual) where T:struct,Enum=>string.IsNullOrWhiteSpace(expected)||string.Equals(expected,actual.ToString(),StringComparison.OrdinalIgnoreCase);
  static LegalEvidenceCandidate Candidate(LegalEvidenceRequirement r,Guid? id,string entity,string? field,string? raw,string? normalized,string? outcome,double? confidence,Guid? doc,Guid? docField,string explanation)=>new(r.EvidenceType,r.Code,entity,id,field,raw,normalized,outcome,confidence,doc,docField,explanation);
  static string? OperationValue(TradeOperation op,string code)=>code.ToUpperInvariant() switch{"OPERATION_TYPE"=>op.OperationType.ToString(),"PEDIMENTO_NUMBER"=>op.PedimentoNumber,"OPERATION_DATE"=>op.OperationDate.ToString("O"),"PEDIMENTO_KEY"=>op.PedimentoKey,"TARIFF_FRACTION"=>op.TariffFraction,"NICO"=>op.Nico,"CUSTOMS_REGIME"=>op.CustomsRegime,"IS_IMMEX"=>op.IsImmex.ToString(),"IS_TEMPORARY_IMPORT"=>op.IsTemporaryImport?.ToString(),"COMMERCIAL_VALUE"=>op.CommercialValue?.ToString(CultureInfo.InvariantCulture),"CURRENCY"=>op.Currency,"QUANTITY"=>op.Quantity?.ToString(CultureInfo.InvariantCulture),_=>null};
}

public sealed record AdvancedLegalAuditSummary(Guid AuditId,DateTime EvaluationDate,int RulesEvaluated,int Compliant,int NonCompliant,int NotApplicable,int InsufficientEvidence,int ManualReview);
public interface ILegalAuditEngineV2 { Task<AdvancedLegalAuditSummary> ExecuteAsync(Guid operationId,Guid userId,CancellationToken ct=default); }

public sealed class LegalAuditEngineV2(SaceDbContext db,ILegalEvidenceResolver resolver):ILegalAuditEngineV2 {
  public async Task<AdvancedLegalAuditSummary> ExecuteAsync(Guid operationId,Guid userId,CancellationToken ct=default){
    var op=await db.TradeOperations.AsNoTracking().SingleOrDefaultAsync(x=>x.Id==operationId,ct)??throw new KeyNotFoundException("OPERATION_NOT_FOUND");
    if(!await db.Users.AnyAsync(x=>x.Id==userId&&x.IsActive,ct))throw new UnauthorizedAccessException("USER_NOT_FOUND");
    var date=op.OperationDate.Date;
    var candidates=await db.NormativeRules.AsSplitQuery().Include(x=>x.LegalConditions).Include(x=>x.LegalEvidenceRequirements).Include(x=>x.LegalEvidenceMappings).Include(x=>x.LegalSourceCitations).ThenInclude(x=>x.OfficialSourceCitation).ThenInclude(x=>x.OfficialLegalSourceVersion).ThenInclude(x=>x.OfficialLegalSource).Where(x=>x.IsLegalRule&&x.RuleCategory==RuleCategory.LEGAL&&x.LegalStatus==LegalRuleStatus.VERIFIED&&x.IsActive&&x.EffectiveFrom<=date&&(x.EffectiveTo==null||date<=x.EffectiveTo)&&x.LegalSourceCitations.Any(c=>c.OfficialSourceCitation.OfficialLegalSourceVersion.VerificationStatus==SourceVerificationStatus.VERIFIED&&c.OfficialSourceCitation.OfficialLegalSourceVersion.OfficialLegalSource.Status==SourceVerificationStatus.VERIFIED)).OrderByDescending(x=>x.Version).ToListAsync(ct);
    var rules=candidates.GroupBy(x=>x.Code).Select(x=>x.First()).OrderBy(x=>x.Code).ToList();
    await using var transaction=await db.Database.BeginTransactionAsync(ct);
    var audit=new Audit{Number=$"AUD-LEGAL-V2-{await db.Audits.CountAsync(ct)+1:D6}",TradeOperationId=op.Id,Period=op.Period,AuditType=AuditType.Legal,Status=AuditStatus.Running,CreatedBy=userId,EvaluationDate=date,EvaluationDateBasis=EvaluationDateBasis.OPERATION_DATE,NormativeVersionLabel=$"LEGAL V2 — fecha jurídica {date:yyyy-MM-dd}"};db.Audits.Add(audit);
    Log(userId,"LEGAL_EVALUATION_STARTED",nameof(Audit),audit.Id,$"Operación {op.Folio}; fecha jurídica {date:yyyy-MM-dd}.");await db.SaveChangesAsync(ct);
    foreach(var rule in rules){
      var evidence=await resolver.ResolveAsync(op,rule,ct);var decision=Decide(rule,evidence);
      var primary=rule.LegalSourceCitations.OrderByDescending(x=>x.IsPrimary).Select(x=>x.OfficialSourceCitation).First();var source=primary.OfficialLegalSourceVersion;
      var result=new AuditResult{AuditId=audit.Id,RuleId=rule.Code,NormativeRuleId=rule.Id,NormativeRuleVersion=rule.Version,RuleCode=rule.Code,RuleVersion=rule.Version,RuleTitle=rule.Name,Outcome=decision.Outcome,Status=Map(decision.Outcome),Message=decision.Rationale,Explanation=decision.Rationale,ApplicabilityExplanation=decision.Applicability,EvidenceExplanation=decision.Evidence,DecisionExplanation=decision.Rationale,DecisionMode=LegalDecisionMode.AUTOMATIC,RequiresManualReview=decision.Outcome==LegalOutcome.MANUAL_REVIEW,EvaluatedAt=DateTime.UtcNow,IsIncludedInLegalCompliance=rule.IsIncludedInLegalCompliance,SourceVersionId=source.Id,SourceCitationSnapshot=JsonSerializer.Serialize(new{source=source.OfficialLegalSource.Title,source.Version,source.PublicationDate,source.EffectiveFrom,source.EffectiveTo,primary.CitationLabel,primary.ExactReferenceText,primary.OfficialUrl}),RuleEffectiveFrom=rule.EffectiveFrom,RuleEffectiveTo=rule.EffectiveTo,EvidenceJson=JsonSerializer.Serialize(evidence),ComparedValuesJson="{}",CalculationJson="{}"};
      result.LegalEvidence.AddRange(evidence.Select(x=>new LegalEvaluationEvidence{EvidenceType=x.EvidenceType,SourceEntityType=x.SourceEntityType,SourceEntityId=x.SourceEntityId,FieldCode=x.FieldCode,RawValue=x.RawValue,NormalizedValue=x.NormalizedValue,Outcome=x.Outcome,Confidence=x.Confidence,DocumentId=x.DocumentId,DocumentFieldId=x.DocumentFieldId,Explanation=x.Explanation,CapturedAt=DateTime.UtcNow}));db.AuditResults.Add(result);Log(userId,"LEGAL_RESULT_CREATED",nameof(AuditResult),result.Id,$"{rule.Code} v{rule.Version}: {decision.Outcome}.");
      if(decision.Outcome==LegalOutcome.NON_COMPLIANT)await CreateFinding(op,audit,rule,result,userId,ct);
    }
    audit.Status=AuditStatus.Completed;audit.CompletedAt=DateTime.UtcNow;Log(userId,"LEGAL_EVALUATION_COMPLETED",nameof(Audit),audit.Id,$"{rules.Count} regla(s) VERIFIED evaluadas.");await db.SaveChangesAsync(ct);await transaction.CommitAsync(ct);
    var outcomes=await db.AuditResults.AsNoTracking().Where(x=>x.AuditId==audit.Id).Select(x=>x.Outcome).ToListAsync(ct);return new(audit.Id,date,outcomes.Count,outcomes.Count(x=>x==LegalOutcome.COMPLIANT),outcomes.Count(x=>x==LegalOutcome.NON_COMPLIANT),outcomes.Count(x=>x==LegalOutcome.NOT_APPLICABLE),outcomes.Count(x=>x==LegalOutcome.INSUFFICIENT_EVIDENCE),outcomes.Count(x=>x==LegalOutcome.MANUAL_REVIEW));
  }
  sealed record Decision(LegalOutcome Outcome,string Applicability,string Evidence,string Rationale);
  static Decision Decide(NormativeRule rule,IReadOnlyList<LegalEvidenceCandidate> evidence){
    var missing=rule.LegalEvidenceRequirements.Where(r=>r.Required&&!evidence.Any(x=>x.Code==r.Code)).ToList();if(missing.Count>0)return new(LegalOutcome.INSUFFICIENT_EVIDENCE,"La aplicabilidad no se presume.",$"Falta evidencia obligatoria: {string.Join(", ",missing.Select(x=>x.Code))}.","No existe prueba suficiente para una conclusión jurídica.");
    if(rule.LegalEvidenceRequirements.Any(x=>x.ManualVerificationRequired))return new(LegalOutcome.MANUAL_REVIEW,"Regla potencialmente aplicable.","La evidencia configurada exige verificación humana.","Se requiere revisión humana; no se presume incumplimiento.");
    var applicability=rule.LegalConditions.Where(x=>x.FailureBehavior==LegalFailureBehavior.NOT_APPLICABLE).ToList();if(applicability.Count>0&&!GroupsPass(applicability,evidence))return new(LegalOutcome.NOT_APPLICABLE,"Las condiciones de aplicabilidad no se satisfacen.","La evidencia se conserva para trazabilidad.","La regla no aplica a esta operación.");
    var tests=rule.LegalConditions.Where(x=>x.FailureBehavior!=LegalFailureBehavior.NOT_APPLICABLE).ToList();if(tests.Count==0)return new(LegalOutcome.MANUAL_REVIEW,"Regla aplicable.","Evidencia completa.","No existe una prueba jurídica automática configurada.");
    if(GroupsPass(tests,evidence))return new(LegalOutcome.COMPLIANT,"Regla aplicable.","Todos los requisitos de evidencia están presentes.","Las condiciones jurídicas configuradas se satisfacen.");
    var behavior=tests.Where(x=>!ConditionPass(x,evidence)).Select(x=>x.FailureBehavior).FirstOrDefault();var outcome=behavior switch{LegalFailureBehavior.MANUAL_REVIEW=>LegalOutcome.MANUAL_REVIEW,LegalFailureBehavior.INSUFFICIENT_EVIDENCE=>LegalOutcome.INSUFFICIENT_EVIDENCE,_=>LegalOutcome.NON_COMPLIANT};return new(outcome,"Regla aplicable.","La evidencia requerida está completa.",outcome==LegalOutcome.NON_COMPLIANT?"La prueba jurídica configurada no se satisface; se crea hallazgo trazable.":"La condición requiere intervención humana o información adicional.");
  }
  static bool GroupsPass(IReadOnlyList<LegalRuleCondition> conditions,IReadOnlyList<LegalEvidenceCandidate> evidence)=>conditions.GroupBy(x=>x.GroupCode).Any(g=>g.OrderBy(x=>x.Sequence).All(x=>ConditionPass(x,evidence)));
  static bool ConditionPass(LegalRuleCondition c,IReadOnlyList<LegalEvidenceCandidate> evidence){var values=evidence.Where(x=>x.Code==c.FieldCode||x.FieldCode==c.FieldCode).Select(x=>x.NormalizedValue??x.RawValue).Where(x=>x is not null).Cast<string>().ToList();if(c.Operator==LegalConditionOperator.NOT_PRESENT)return values.Count==0;if(c.Operator==LegalConditionOperator.PRESENT)return values.Any(x=>!string.IsNullOrWhiteSpace(x));if(values.Count==0)return !c.Required;return values.Any(v=>Compare(v,c));}
  static bool Compare(string actual,LegalRuleCondition c){var expected=c.ExpectedValue??"";return c.Operator switch{LegalConditionOperator.EQUALS=>Eq(actual,expected),LegalConditionOperator.NOT_EQUALS=>!Eq(actual,expected),LegalConditionOperator.IN=>Split(expected).Any(x=>Eq(actual,x)),LegalConditionOperator.NOT_IN=>Split(expected).All(x=>!Eq(actual,x)),LegalConditionOperator.BOOLEAN_TRUE=>bool.TryParse(actual,out var b)&&b,LegalConditionOperator.BOOLEAN_FALSE=>bool.TryParse(actual,out var b)&&!b,LegalConditionOperator.GREATER_THAN=>Num(actual)>Num(expected),LegalConditionOperator.GREATER_OR_EQUAL=>Num(actual)>=Num(expected),LegalConditionOperator.LESS_THAN=>Num(actual)<Num(expected),LegalConditionOperator.LESS_OR_EQUAL=>Num(actual)<=Num(expected),LegalConditionOperator.BETWEEN=>Num(actual)>=Num(expected)&&Num(actual)<=Num(c.ExpectedValue2),LegalConditionOperator.DATE_BEFORE=>Date(actual)<Date(expected),LegalConditionOperator.DATE_AFTER=>Date(actual)>Date(expected),_=>false};}
  static bool Eq(string a,string b)=>string.Equals(a.Trim(),b.Trim(),StringComparison.OrdinalIgnoreCase);static string[] Split(string x)=>x.Split([',',';','|'],StringSplitOptions.RemoveEmptyEntries|StringSplitOptions.TrimEntries);static decimal Num(string? x)=>decimal.TryParse(x,NumberStyles.Any,CultureInfo.InvariantCulture,out var n)?n:decimal.MinValue;static DateTime Date(string x)=>DateTime.TryParse(x,CultureInfo.InvariantCulture,DateTimeStyles.AssumeUniversal,out var d)?d:DateTime.MinValue;
  async Task CreateFinding(TradeOperation op,Audit audit,NormativeRule rule,AuditResult result,Guid user,CancellationToken ct){if(await db.Findings.AnyAsync(x=>x.OriginalAuditResultId==result.Id,ct))return;var documentType=await db.DocumentTypes.Where(x=>x.Code=="OTHER").FirstAsync(ct);var item=new Finding{AuditId=audit.Id,TradeOperationId=op.Id,DocumentTypeId=documentType.Id,RuleId=rule.Code,Number=$"HAL-LEGAL-{await db.Findings.CountAsync(ct)+1:D6}",Severity=Severity.High,Description=result.DecisionExplanation??result.Message,CorrectionResponsible=documentType.CorrectionResponsible,Status=FindingStatus.OPEN,OriginalAuditResultId=result.Id,LatestAuditResultId=result.Id};db.Findings.Add(item);db.FindingHistories.Add(new(){FindingId=item.Id,NewStatus=FindingStatus.OPEN,Comment=$"Hallazgo LEGAL V2 por {rule.Code} v{rule.Version}.",ChangedBy=user});Log(user,"LEGAL_FINDING_CREATED",nameof(Finding),item.Id,$"{rule.Code} v{rule.Version}; prioridad operativa High.");}
  void Log(Guid user,string action,string entity,Guid id,string details)=>db.SystemAuditLogs.Add(new(){UserId=user,Action=action,EntityType=entity,EntityId=id.ToString(),Details=details});
  static ResultStatus Map(LegalOutcome x)=>x switch{LegalOutcome.COMPLIANT=>ResultStatus.Valid,LegalOutcome.NON_COMPLIANT=>ResultStatus.Invalid,LegalOutcome.NOT_APPLICABLE=>ResultStatus.NotApplicable,LegalOutcome.INSUFFICIENT_EVIDENCE=>ResultStatus.Missing,_=>ResultStatus.Warning};
}

public interface ILegalReviewService { Task<LegalReviewDecision> ReviewAsync(Guid resultId,Guid userId,LegalReviewDecisionType decision,LegalOutcome? outcome,string reason,CancellationToken ct=default); }
public sealed class LegalReviewService(SaceDbContext db):ILegalReviewService {
  public async Task<LegalReviewDecision> ReviewAsync(Guid resultId,Guid userId,LegalReviewDecisionType decision,LegalOutcome? outcome,string reason,CancellationToken ct=default){
    if(string.IsNullOrWhiteSpace(reason))throw new InvalidOperationException("REVIEW_REASON_REQUIRED");var result=await db.AuditResults.Include(x=>x.Audit).SingleOrDefaultAsync(x=>x.Id==resultId&&x.Outcome!=null,ct)??throw new KeyNotFoundException("LEGAL_RESULT_NOT_FOUND");if(decision!=LegalReviewDecisionType.REQUEST_INFORMATION&&outcome is null)throw new InvalidOperationException("REVIEW_OUTCOME_REQUIRED");var finding=await db.Findings.FirstOrDefaultAsync(x=>x.OriginalAuditResultId==result.Id&&x.Status!=FindingStatus.DISMISSED,ct);var review=new LegalReviewDecision{AuditResultId=result.Id,FindingId=finding?.Id,ReviewerUserId=userId,PreviousOutcome=result.Outcome!.Value,ReviewedOutcome=outcome,Decision=decision,Reason=reason.Trim()};db.LegalReviewDecisions.Add(review);result.ManualOutcome=outcome;result.ReviewerUserId=userId;result.ReviewedAt=review.ReviewedAt;result.ReviewComment=reason.Trim();result.DecisionMode=LegalDecisionMode.AUTOMATIC_REVIEWED;
    if(decision==LegalReviewDecisionType.OVERRIDE&&outcome==LegalOutcome.NON_COMPLIANT&&finding is null){var op=await db.TradeOperations.FindAsync([result.Audit.TradeOperationId!.Value],ct);var rule=await db.NormativeRules.FindAsync([result.NormativeRuleId!.Value],ct);var doc=await db.DocumentTypes.FirstAsync(x=>x.Code=="OTHER",ct);finding=new Finding{AuditId=result.AuditId,TradeOperationId=op!.Id,DocumentTypeId=doc.Id,RuleId=result.RuleCode??result.RuleId,Number=$"HAL-LEGAL-{await db.Findings.CountAsync(ct)+1:D6}",Severity=Severity.High,Description=reason.Trim(),CorrectionResponsible=doc.CorrectionResponsible,Status=FindingStatus.OPEN,OriginalAuditResultId=result.Id,LatestAuditResultId=result.Id};db.Findings.Add(finding);review.FindingId=finding.Id;}
    if(finding is not null&&outcome==LegalOutcome.COMPLIANT){finding.Status=FindingStatus.DISMISSED;finding.DismissedBy=userId;finding.DismissedAt=DateTime.UtcNow;finding.DismissalReason=reason.Trim();finding.UpdatedAt=DateTime.UtcNow;db.FindingHistories.Add(new(){FindingId=finding.Id,PreviousStatus=FindingStatus.OPEN,NewStatus=FindingStatus.DISMISSED,Comment=reason.Trim(),ChangedBy=userId});}
    db.SystemAuditLogs.Add(new(){UserId=userId,Action=decision==LegalReviewDecisionType.REQUEST_INFORMATION?"LEGAL_REVIEW_REQUESTED":"LEGAL_REVIEW_COMPLETED",EntityType=nameof(AuditResult),EntityId=result.Id.ToString(),Details=$"{decision}: {result.Outcome} → {outcome}; razón registrada."});await db.SaveChangesAsync(ct);return review;
  }
}
